// Illustrative: these helpers read a finished recording and its saved records. Each group reads the record named by its key.
import { filter, from, groupBy, map, mergeMap, toArray } from 'rxjs';
const refusals$ = from(readEventsFor('Setup guide', example.parameters.windowMinutes)).pipe(
  filter(event => event.kind === 'Edit blocked')
);

const gateRows$ = refusals$.pipe(
  groupBy(edit => edit.gateRunId),
  mergeMap(run$ => run$.pipe(toArray(), map(refusals =>
    ({ ...readGateRow(run$.key, 'Guide links'), refusals })
  )))
);

const orders$ = gateRows$.pipe(
  groupBy(row => row.orderId),
  mergeMap(order$ => order$.pipe(toArray(), map(evidence =>
    ({ ...readWorkOrder(order$.key), evidence })
  )))
);

const planningPasses$ = orders$.pipe(
  groupBy(order => order.passId),
  mergeMap(pass$ => pass$.pipe(toArray(), map(assignments =>
    ({ ...readPlanningPass(pass$.key), assignments })
  )))
);

